// AWI: ganti semua foto profil sales di front-end ke foto baru (12 Nov 2026).
add_action('template_redirect', function () {
	if (is_admin() || wp_doing_ajax() || (defined('REST_REQUEST') && REST_REQUEST) || is_feed()) return;
	ob_start(function ($html) {
		if (strpos($html, 'awi-') === false) return $html;
		$up = 'https://byd-makassar.id/wp-content/uploads/';
		$sq = $up . '2026/11/awi-sales-byd-makassar-avatar.webp';
		$pt = $up . '2026/11/awi-sales-consultant-byd-makassar-profil-2.webp';
		$tl = $up . '2026/11/awi-sales-byd-makassar-3d-full.webp';
		$html = preg_replace_callback('#(?:https?:)?//byd-makassar\.id/wp-content/uploads/2026/05/awi-nyd-makassar(-(\d+)x(\d+))?\.jpg#', function ($m) use ($sq, $pt) {
			return (!empty($m[1]) && $m[2] === $m[3]) ? $sq : $pt;
		}, $html);
		$html = preg_replace_callback('#https?:\\\\/\\\\/byd-makassar\.id\\\\/wp-content\\\\/uploads\\\\/2026\\\\/05\\\\/awi-nyd-makassar(-(\d+)x(\d+))?\.jpg#', function ($m) use ($sq, $pt) {
			$u = (!empty($m[1]) && $m[2] === $m[3]) ? $sq : $pt;
			return str_replace('/', '\\/', $u);
		}, $html);
		$html = str_replace($up . '2026/11/awi-sales-byd-makassar-studio.webp', $tl, $html);
		$html = preg_replace('#(?:https?:)?//secure\.gravatar\.com/avatar/0a3064daeef586504d6271d352875b51e50abca2a72f0212bb64ebab0c8d0597[^"\x27\s]*#', $sq, $html);
		$html = str_replace(str_replace('/', '\\/', $up . '2026/11/awi-sales-byd-makassar-studio.webp'), str_replace('/', '\\/', $tl), $html);
		return $html;
	});
}, 0);

add_filter('pre_get_avatar_data', function ($args, $id) {
	if (is_admin()) return $args;
	$uid = 0;
	if (is_numeric($id)) $uid = (int) $id;
	elseif ($id instanceof WP_User) $uid = $id->ID;
	elseif ($id instanceof WP_Post) $uid = (int) $id->post_author;
	elseif ($id instanceof WP_Comment) $uid = (int) $id->user_id;
	elseif (is_string($id) && is_email($id)) { $u = get_user_by('email', $id); if ($u) $uid = $u->ID; }
	if ($uid === 6) {
		$args['url'] = 'https://byd-makassar.id/wp-content/uploads/2026/11/awi-sales-byd-makassar-avatar.webp';
		$args['found_avatar'] = true;
	}
	return $args;
}, 10, 2);
